import NavBar from './NavBar';
import SlideImage from './SlideImage';
import GetOff from './GetOff';
import TopCollection from './TopCollection';

export default function Home() {
  return (
    <>
      <NavBar />
      <SlideImage />
      <GetOff />
      <TopCollection />
    </>
  );
}
